import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1]) % n
    nums = data[2:2+n]
    if k > 0:
        nums = nums[-k:] + nums[:-k]
    print(" ".join(nums))

if __name__ == '__main__':
    solve()

