#include <stdio.h>
#include <stdlib.h>

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    k = k % n;
    long long *arr = (long long*)malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) scanf("%lld", &arr[i]);
    for (int i = 0; i < n; i++) {
        int src = (i - k + n) % n;
        printf("%lld%s", arr[src], (i == n - 1) ? "\n" : " ");
    }
    free(arr);
    return 0;
}
